/*
 * A044521  Numbers n such that string 0,2 occurs in the base 7 representation
 *          of n but not of n+1.
 * https://oeis.org/A044521
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n‑th integer such that the base‑7 representation of
 *            the integer * contains the consecutive digits '0' followed by
 *            '2', but the same does NOT occur in * the base‑7 representation
 *            of the integer + 1. * The sequence is generated by scanning the
 *            natural numbers and keeping those that * sa...
 * Range:     u8 n <= 5, u16 n <= 42, u32 n <= 42, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Helpers:   has_02_uint64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/has_02_uint64.h"

/* Memoisation storage for computed terms. */
static seq_t* cache  = NULL;
static size_t cache_cap = 0;
static size_t cache_len = 0;
static uint64_t cur = 1;        /* next candidate to test */

/* Grow the cache when needed. */
static void grow_cache(void)
{
    size_t new_cap = (cache_cap == 0) ? 16 : cache_cap * 2;
    seq_t* tmp = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) exit(1);
    cache = tmp;
    cache_cap = new_cap;
}

/* Return the n-th term (n≥1) of OEIS A044521. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;    /* undefined for n<1, return 0 as a safe default */

    while (cache_len < n) {
        if (has_02_uint64(cur) && !has_02_uint64(cur + 1)) {
            if (cache_len == cache_cap) grow_cache();
            cache[cache_len] = (seq_t)cur;   /* conversion ok for built‑in and big‑int types */
            cache_len++;
        }
        cur++;
    }
    return cache[n - 1];
}
